import importlib
import inspect
from typing import Dict, Any, Tuple
from tools.base import BaseTool


class ToolExecutor:
    """
    Localized tool execution abstraction that encapsulates import, instantiation,
    execution, and error handling for tools.
    """

    def __init__(self):
        # Cache tool classes to avoid repeated inspection
        self._tool_class_cache: Dict[str, type] = {}

    def execute(self, tool_name: str, tool_input: Dict[str, Any]) -> Tuple[bool, Any]:
        """
        Execute the specified tool with the given input.

        Returns:
            Tuple of (success: bool, result: Any)
            - On success: (True, tool's return value)
            - On failure: (False, error message string)
        """
        try:
            # Load the tool module
            try:
                module = importlib.import_module(f'tools.{tool_name}')
            except ImportError as e:
                return False, f"Failed to import tool '{tool_name}': {str(e)}"

            # Get the tool class
            tool_class = self._get_tool_class(module, tool_name)
            if tool_class is None:
                return False, f"Tool class not found for '{tool_name}'"

            # Instantiate and execute
            try:
                tool_instance = tool_class()
                result = tool_instance.execute(**tool_input)
                return True, result
            except TypeError:
                return False, f"Tool '{tool_name}' not instantiable (missing required constructor args)"
            except Exception as e:
                return False, f"Error executing tool '{tool_name}': {str(e)}"

        except Exception as e:
            return False, f"Unexpected error executing tool '{tool_name}': {str(e)}"

    def _get_tool_class(self, module, tool_name: str) -> type:
        """
        Retrieve the tool class from the module by name, using caching.
        """
        # Check cache first to avoid repeated inspection
        if tool_name in self._tool_class_cache:
            return self._tool_class_cache[tool_name]

        # Find tool class by matching name property
        for name, obj in inspect.getmembers(module, inspect.isclass):
            if issubclass(obj, BaseTool) and obj is not BaseTool:
                try:
                    if obj().name == tool_name:
                        self._tool_class_cache[tool_name] = obj
                        return obj
                except Exception:
                    # Skip tools that fail instantiation during lookup
                    continue

        return None
